<?php
declare(strict_types=1);

function qa180_register_upgrade(App $app,int $tenantId=0):void {
    // Preserve the existing paired devices and primary assignment. Registers
    // are separate records; this never chooses an offline principal.
    $app->exec('INSERT INTO fisitaap_registers180(tenant_id,branch_id,name,device_id) SELECT d.tenant_id,d.branch_id,LEFT(CONCAT("Caja · ",d.name),100),d.id FROM fisitaap_r2_devices d LEFT JOIN fisitaap_registers180 r ON r.device_id=d.id WHERE d.is_active=1 AND d.token_hash IS NOT NULL AND r.id IS NULL'.($tenantId?' AND d.tenant_id=?':''),$tenantId?[$tenantId]:[]);
    if(r18_ready($app))r18_assign_register_numbers($app);
}
function qa180_devices(App $app,array $user,?array $tenant):void {
    if(!$tenant){
        if(is_post()){http_response_code(403);simple_error('Consulta de equipos','Cada dueño configura las cajas de su negocio.');return;}
        $tid=(int)($_GET['tenant_id']??0);admin_shell_start('Equipos y cajas',$user,null,'escritorio');echo '<section class="card admin-card"><form class="qa180-filter" method="get"><label>Negocio'.r2_select('tenant_id',$app->all('SELECT id,name FROM tenants WHERE is_active=1 AND slug NOT REGEXP "^demo-(restaurante|tienda)-[0-9a-f]{32}$" ORDER BY name'),$tid,'name',true).'</label><button class="btn">Ver equipos</button></form><div class="table-wrap"><table class="table"><tr><th>Negocio / sucursal</th><th>Equipo</th><th>Caja</th><th>Usuario asignado</th><th>Última conexión</th><th>Estado</th></tr>';
        foreach($app->all('SELECT d.id,d.name device,d.is_active,d.last_sync,t.name tenant,b.name branch,r.name register_name,u.name cashier FROM fisitaap_r2_devices d JOIN tenants t ON t.id=d.tenant_id JOIN branches b ON b.id=d.branch_id AND b.tenant_id=d.tenant_id LEFT JOIN fisitaap_registers180 r ON r.device_id=d.id AND r.tenant_id=d.tenant_id LEFT JOIN users u ON u.id=r.user_id AND u.tenant_id=d.tenant_id WHERE (?=0 OR d.tenant_id=?) ORDER BY t.name,d.id DESC LIMIT 400',[$tid,$tid]) as $d)echo '<tr><td>'.e($d['tenant'].' · '.$d['branch']).'</td><td>'.e($d['device']).'</td><td>'.e($d['register_name']??'Sin asignar').'</td><td>'.e($d['cashier']??'Cajeros autorizados del negocio').'</td><td>'.e($d['last_sync']??'Pendiente').'</td><td>'.($d['is_active']?'Activo':'Inactivo').'</td></tr>';echo '</table></div></section>';admin_shell_end();return;
    }
    qa180_permission($app,$user,'escritorio','configure');
    if(is_post()){verify_csrf();try{
        $action=(string)($_POST['action']??'');$bid=(int)($_POST['branch_id']??0);$branch=$app->one('SELECT id FROM branches WHERE id=? AND tenant_id=? AND is_active=1',[$bid,$tenant['id']]);if(!$branch)throw new DomainException('Selecciona una sucursal del negocio.');
        if($action==='primary'){primary179_select($app,$tenant,(int)($_POST['id']??0));}
        else{
            $app->db->beginTransaction();$app->one('SELECT id FROM tenants WHERE id=? FOR UPDATE',[$tenant['id']]);$app->one('SELECT id FROM branches WHERE id=? AND tenant_id=? FOR UPDATE',[$bid,$tenant['id']]);
            if($action==='pair'){
                $name=mb_substr(trim((string)($_POST['name']??'')),0,120);if($name==='')throw new DomainException('Escribe un nombre para identificar el equipo.');$code=bin2hex(random_bytes(16));
                $app->exec('INSERT INTO fisitaap_r2_devices(tenant_id,branch_id,name,pair_hash,pair_expires) VALUES(?,?,?,?,DATE_ADD(NOW(),INTERVAL 30 MINUTE))',[$tenant['id'],$bid,$name,hash('sha256',$code)]);$id=(int)$app->db->lastInsertId();$_SESSION['pair180_once']=['tenant'=>$tenant['id'],'id'=>$id,'code'=>$code];
                qa180_audit($app,$user,'device_pair','device',$id,'Creó un código temporal para conectar '.$name);
            }elseif($action==='register'){
                $id=(int)($_POST['id']??0);$device=(int)($_POST['device_id']??0);$cashier=(int)($_POST['user_id']??0);$name=mb_substr(trim((string)($_POST['name']??'')),0,100);if($name==='')throw new DomainException('Escribe el nombre de la caja.');
                $old=$id?$app->one('SELECT * FROM fisitaap_registers180 WHERE id=? AND tenant_id=? FOR UPDATE',[$id,$tenant['id']]):null;if($id&&!$old)throw new DomainException('Caja no disponible.');
                $active=isset($_POST['is_active'])?1:0;$drawer=isset($_POST['drawer_enabled'])?1:0;
                $number=r18_register_number($app,$tenant,$id,$_POST['number_r18']??($old['number_r18']??($id?:1)));
                $scopeChange=$old&&((int)($old['number_r18']??$old['id'])!==$number||(int)$old['branch_id']!==$bid||$old['name']!==$name||(int)$old['device_id']!==$device||(int)$old['user_id']!==$cashier||(int)$old['is_active']!==$active);
                if($scopeChange&&$app->one('SELECT id FROM pos_shifts WHERE tenant_id=? AND register_id=? AND status="open"',[$tenant['id'],$id]))throw new DomainException('Cierra el turno de esta caja antes de cambiar su equipo, cajero o configuración.');
                if($scopeChange&&$old['device_id']&&$app->one('SELECT tenant_id FROM fisitaap_primary179 WHERE tenant_id=? AND device_id=?',[$tenant['id'],$old['device_id']]))throw new DomainException('Sincroniza y libera la función principal desde su aplicación antes de cambiar la caja asignada. Así se conservan los turnos y ventas pendientes.');
                if($device){$d=$app->one('SELECT id FROM fisitaap_r2_devices WHERE id=? AND tenant_id=? AND branch_id=? AND is_active=1 AND token_hash IS NOT NULL',[$device,$tenant['id'],$bid]);if(!$d)throw new DomainException('El equipo debe estar conectado y pertenecer a esta sucursal.');if($app->one('SELECT id FROM fisitaap_registers180 WHERE device_id=? AND id<>?',[$device,$id]))throw new DomainException('El equipo ya tiene otra caja asignada. Desvincúlala primero.');}
                if($cashier){$staff=$app->one('SELECT * FROM users WHERE id=? AND tenant_id=? AND is_active=1',[$cashier,$tenant['id']]);if(!$staff||!r2_offline_allowed($app,$staff))throw new DomainException('Selecciona un usuario existente, activo y autorizado para cobrar.');}
                $active=isset($_POST['is_active'])?1:0;$drawer=isset($_POST['drawer_enabled'])?1:0;
                if($id)$app->exec('UPDATE fisitaap_registers180 SET branch_id=?,name=?,device_id=?,user_id=?,is_active=?,drawer_enabled=?,number_r18=? WHERE id=? AND tenant_id=?',[$bid,$name,$device?:null,$cashier?:null,$active,$drawer,$number,$id,$tenant['id']]);
                else{$app->exec('INSERT INTO fisitaap_registers180(tenant_id,branch_id,name,device_id,user_id,is_active,drawer_enabled,number_r18) VALUES(?,?,?,?,?,?,?,?)',[$tenant['id'],$bid,$name,$device?:null,$cashier?:null,$active,$drawer,$number]);$id=(int)$app->db->lastInsertId();}
                if($active&&$number>0){$freshRegister=$app->one('SELECT * FROM fisitaap_registers180 WHERE id=? AND tenant_id=?',[$id,$tenant['id']]);r18_ensure_funds($app,$tenant,$freshRegister);}
                qa180_audit($app,$user,'register_save','register',$id,'Configuró '.$name.' y su equipo / usuario autorizado');
            }elseif($action==='revoke'){
                $id=(int)($_POST['id']??0);$d=$app->one('SELECT * FROM fisitaap_r2_devices WHERE id=? AND tenant_id=? AND branch_id=? FOR UPDATE',[$id,$tenant['id'],$bid]);if(!$d)throw new DomainException('Equipo no disponible.');
                if(primary179_policy($app,$d)['allowed'])throw new DomainException('Sincroniza, cierra turnos y libera el principal desde su aplicación antes de desactivarlo.');
                if($app->one('SELECT s.id FROM pos_shifts s JOIN fisitaap_registers180 r ON r.id=s.register_id AND r.tenant_id=s.tenant_id WHERE r.device_id=? AND s.status="open"',[$id]))throw new DomainException('Cierra el turno de esta caja antes de desactivar el equipo.');
                $app->exec('UPDATE fisitaap_r2_devices SET is_active=0,token_hash=NULL,pair_hash=NULL WHERE id=? AND tenant_id=?',[$id,$tenant['id']]);qa180_audit($app,$user,'device_revoke','device',$id,'Desactivó el equipo '.$d['name']);
            }else throw new DomainException('Acción no disponible.');$app->db->commit();
        }
        flash('success','Equipos y cajas guardados.');
    }catch(Throwable $error){if($app->db->inTransaction())$app->db->rollBack();flash('error',$error instanceof PDOException?'No se guardó la configuración. Revisa las asignaciones antes de repetir.':$error->getMessage());}redirect(url('admin/escritorio'));}
    $branches=$app->all('SELECT id,name FROM branches WHERE tenant_id=? AND is_active=1 ORDER BY name',[$tenant['id']]);$devices=$app->all('SELECT d.*,b.name branch FROM fisitaap_r2_devices d JOIN branches b ON b.id=d.branch_id AND b.tenant_id=d.tenant_id WHERE d.tenant_id=? ORDER BY d.id DESC',[$tenant['id']]);$staff=[];foreach($app->all('SELECT * FROM users WHERE tenant_id=? AND is_active=1 ORDER BY name',[$tenant['id']]) as $member)if(r2_offline_allowed($app,$member))$staff[]=$member;$pair=session_take176('pair180_once');
    admin_shell_start('Equipos y cajas',$user,$tenant,'escritorio');echo '<section class="card admin-card"><h2>Equipo, caja y usuario</h2><p>Un equipo es el Windows o Android instalado. Una caja es el punto de atención de un equipo. Caja 0 abre cuentas y atiende; las numeradas cobran con el usuario que abrió su turno. El cajero se elige entre los usuarios activos con permiso de cobrar y usa su contraseña habitual. No se crean usuarios ni contraseñas locales adicionales.</p><p>Solo el principal de todo el negocio puede vender sin internet. Los secundarios usan el sistema completo conectado a la web, aunque descubran su dirección mediante el Windows central.</p></section>';primary179_admin($app,$tenant);
    if($pair&&(int)$pair['tenant']===(int)$tenant['id'])echo '<section class="card admin-card"><h2>Conectar este equipo</h2><p>Dirección web: <strong>'.e(rtrim(url(),'/')).'</strong><br>Número de equipo: <strong>'.(int)$pair['id'].'</strong><br>Código de conexión: <code>'.e($pair['code']).'</code></p><p>El código sirve una vez y vence en 30 minutos. Conecta la aplicación y después asígnale una caja aquí.</p></section>';
    echo '<section class="card admin-card"><h2>Registrar equipo</h2>'.r2_form('pair').'<div class="qa180-filter"><label>Sucursal'.r2_select('branch_id',$branches).'</label>'.field('Nombre del Windows o Android','name','',true).'<button class="btn">Crear código de conexión</button></div></form></section>';
    echo '<section class="card admin-card"><h2>Cajas</h2>';foreach([null,...$app->all('SELECT * FROM fisitaap_registers180 WHERE tenant_id=? ORDER BY name',[$tenant['id']])] as $register){echo r2_form('register',(int)($register['id']??0)).'<h3>'.($register?e($register['name']):'Nueva caja').'</h3><div class="qa180-filter">'.field('Nombre de la caja','name',$register['name']??'',true).field('Número: 0 atiende, 1 o más cobra','number_r18',$register['number_r18']??($register['id']??1),true,'number','1').'<label>Sucursal'.r2_select('branch_id',$branches,(int)($register['branch_id']??($branches[0]['id']??0))).'</label><label>Equipo conectado'.r2_select('device_id',array_values(array_filter($devices,fn($d)=>$d['is_active']&&$d['token_hash'])),(int)($register['device_id']??0),'name',true).'</label><label>Cajero asignado'.r2_select('user_id',$staff,(int)($register['user_id']??0),'name',true).'</label></div><p>Sin cajero fijo: admite a los usuarios del negocio autorizados para cobrar. Un equipo solo puede tener una caja.</p><label><input type="checkbox" name="is_active" '.(($register['is_active']??1)?'checked':'').'> Caja activa</label><label><input type="checkbox" name="drawer_enabled" '.(!empty($register['drawer_enabled'])?'checked':'').'> Permitir gaveta en recibos de esta caja</label><button class="btn btn-light">Guardar caja</button></form><hr>';}echo '</section><section class="card admin-card"><h2>Equipos registrados</h2><div class="table-wrap"><table class="table"><tr><th>Equipo</th><th>Sucursal</th><th>Última conexión</th><th>Estado</th><th></th></tr>';
    foreach($devices as $d)echo '<tr><td>'.e($d['name']).'</td><td>'.e($d['branch']).'</td><td>'.e($d['last_sync']??'Todavía sin conexión').'</td><td>'.($d['is_active']?'Activo':'Inactivo').'</td><td>'.($d['is_active']?r2_form('revoke',(int)$d['id']).pos_hidden_148('branch_id',$d['branch_id']).'<button class="btn btn-danger">Desactivar equipo</button></form>':'').'</td></tr>';echo '</table></div></section>';admin_shell_end();
}
